UpdateContext({
    locKeepExpandedID: LookUp(colAdminContracts, !IsFolded).'BoP Contracts Standard Assumptions'
});
If(
    locDevContractLimitExceeded,
    Notify(
        "Maximum 10 development contracts allowed for " & 
        cmp_AdminContraacts_NestedCountryPickerColumn.SelectedCountry.Name & 
        " - " & 
        cmp_AdminContraacts_NestedCountryPickerColumn.SelectedNestedValue,
        NotificationType.Warning
    ),
    UpdateContext(
        {
            locIsVisibleBoPStandardAssumptionContract: true,
            locContractTypeBoPAssumption: 'BoP Contract Types'.'Development Contract',
            locSelectedBoPStandardContract: Blank(),
            locContractDevCoCostsDirty: false,
            locSelectedContractMarginPercentage: Blank(), 
            locSelectedContractMarginFixedValues: Blank(),
            locSelectedContractMarginType :'Contract Margin Type'.Percentage
        }
    );
    With(
        {
            // 1. Pre-calculate Technology (Delegation Fix)
            varTargetTechnology: Switch(
                cmp_AdminContraacts_NestedCountryPickerColumn.SelectedNestedValue,
                "PV", Technology.PV,
                "Wind", Technology.Wind,
                "BESS", Technology.BESS,
                "Hydro", Technology.Hydro
            ),
            varContractTypesChoices: 'BoP Contract Types'
        },

        // 2. Reset Collection
        ClearCollect(
            col_Edit_DevCoCosts,
            SortByColumns(colCapexAllAccounts, "Nummer", SortOrder.Ascending)
        );

        // 3. Fetch ALL existing costs (Conflicts)
        With(
            {
                varScopeCosts: Filter(
                    'BoP Contracts Standard Assumption DevCo Costs',
                    'BoP Contract Standard Assumption'.Country.Name = cmp_AdminContraacts_NestedCountryPickerColumn.SelectedCountry.Name,
                    'BoP Contract Standard Assumption'.Technology = varTargetTechnology
                )
            },

            // 4. Mark EVERYTHING found as 'Used' (New contracts own nothing, so everything found is a conflict)
            ForAll(
                varScopeCosts As Source,
                UpdateIf(
                    col_Edit_DevCoCosts,
                    Id = Source.'CAPEX Account'.'CAPEX Account List',
                    {
                        Selected: false,
                        Used: true,
                        UsedInContractDevCo: Source.'BoP Contract Standard Assumption'.'BoP Contracts Standard Assumptions'
                    }
                )
            )
        )
    );
)

