// Simply flip the state for this specific item. 
// Since we removed the "Reset all to true" logic, others will stay expanded.
Patch(
    colAdminContracts,
    ThisItem,
    { IsFolded: !ThisItem.IsFolded }
);

// Optional: Track the last interacted ID for UI focus logic
UpdateContext({ locLastExpandedID: ThisItem.'BoP Contracts Standard Assumptions' });

ControlPropertyState.AutoRuleBindingString:
// 1. STATE CHECK: Capture if the clicked item is currently expanded
With(
    {varIsCurrentlyExpanded: !ThisItem.IsFolded},
    // 2. RESET: Always close ALL rows first (Standard Accordion Behavior)
    UpdateIf(
        colAdminContracts,
        !IsFolded,
        {IsFolded: true}
    );
    // 3. CONDITIONAL OPEN: Only run the Open logic if it was NOT previously expanded
If(
        !varIsCurrentlyExpanded,
        // A. Open this specific row
        Patch(
            colAdminContracts,
            ThisItem,
            {IsFolded: false}
        );
        ClearCollect(
            col_View_DevCoCosts,
            GroupBy(
                SortByColumns(
                    AddColumns(
                        Filter(
                            'BoP Contracts Standard Assumption DevCo Costs',
                            'BoP Contract Standard Assumption'.'BoP Contracts Standard Assumptions' = ThisItem.'BoP Contracts Standard Assumptions'
                        ),
                        RootCapexOrder,
                        RootCapexAccount.Order,
                        RootCapexAccountName,
                        RootCapexAccount.Name
                    ),
                    "RootCapexOrder"
                ),
                RootCapexAccountName,
                AggregatedCapexAccount
            )
        )
    )
);

Rules.InvariantScript:
// 1. REFRESH DATASOURCE
Refresh('BoP Contracts Standard Assumptions');

// 2. INITIALIZE COLLECTION (Reset to base state)
ClearCollect(
    col_Edit_DevCoCosts,
    SortByColumns(colCapexAllAccounts, "Nummer", SortOrder.Ascending)
);

// 3. DEFINE SCOPE & FETCH DATA
With(
    {
        // A. Capture the ID of the contract we are editing
        varCurrentContractId: ThisItem.'BoP Contracts Standard Assumptions',

        // B. Pre-calculate the Technology Option Set Value (Delegation Fix)
        varTargetTechnology: Switch(
            cmp_AdminContraacts_NestedCountryPickerColumn.SelectedNestedValue,
            "PV", Technology.PV,
            "Wind", Technology.Wind,
            "BESS", Technology.BESS,
            "Hydro", Technology.Hydro 
            // Add other technologies if necessary
        )
    },
    
    // C. Nested With to use varTargetTechnology in the Filter
    With(
        {
            varScopeCosts: Filter(
                'BoP Contracts Standard Assumption DevCo Costs',
                'BoP Contract Standard Assumption'.Country.Name = cmp_AdminContraacts_NestedCountryPickerColumn.SelectedCountry.Name,
                'BoP Contract Standard Assumption'.Technology = varTargetTechnology
            )
        },

        // 4. ITERATE AND FLAG (Classify: Selected vs Used)
        ForAll(
            varScopeCosts As Source,
            UpdateIf(
                col_Edit_DevCoCosts,
                Id = Source.'CAPEX Account'.'CAPEX Account List',
                {
                    // Selected = It belongs to ME
                    Selected: (Source.'BoP Contract Standard Assumption'.'BoP Contracts Standard Assumptions' = varCurrentContractId),
                    
                    // Used = It belongs to SOMEONE ELSE
                    Used: (Source.'BoP Contract Standard Assumption'.'BoP Contracts Standard Assumptions' <> varCurrentContractId),
                    
                    // Metadata for tooltips/debugging
                    UsedInContractDevCo: Source.'BoP Contract Standard Assumption'.'BoP Contracts Standard Assumptions',
                    ContractDevCo: Source.'BoP Contracts Standard Assumption DevCo Costs'
                }
            )
        )
    )
);

// 5. OPEN PANEL & SET VARIABLES
UpdateContext({
    locIsVisibleBoPStandardAssumptionContract: true,
    locContractTypeBoPAssumption: ThisItem.'Contract Types',
    locSelectedBoPStandardContract: ThisItem,
    locContractDevCoCostsDirty: false,        
    locSelectedContractMarginPercentage: ThisItem.'Margin Percentage',    
    locSelectedContractMarginFixedValues: ThisItem.'Margin Fixed Value',
