    },
    If(
        varIsCurrentlyFolded,
        // ====================================================
        // CASE 1: The Row is currently CLOSED -> EXPAND IT
        // ====================================================
        
        // 1. Close ALL other rows first (Accordion style)
        UpdateIf(
            col_Edit_DevCoCosts, 
