// Existing Image Property Logic
With(
    {
        // 1. Define the Pools
        _ChildPool: Filter(
            col_Edit_DevCoCosts,
            ParentId = ThisItem.Id && Level = 3
        ),
        _AvailablePool: Filter(
            col_Edit_DevCoCosts,
            ParentId = ThisItem.Id && Level = 3 && !Used
        ),
        _SelectedPool: Filter(
            col_Edit_DevCoCosts,
            ParentId = ThisItem.Id && Level = 3 && Selected && !Used
        )
    },
    With(
        {
            _TotalCount: CountRows(_ChildPool),        // All children (Used + Unused)
            _AvailableCount: CountRows(_AvailablePool), // Only Unused
            _SelectedCount: CountRows(_SelectedPool)    // Selected by user
        },
        With(
            {
                // 2. DETERMINE STATE
                _State: If(
                    // CASE A: Everything is locked by others
                    _AvailableCount = 0,
                    "LOCKED",

                    // CASE B: Nothing is selected
                    _SelectedCount = 0,
                    "UNCHECKED",

                    // CASE C: (NEW LOGIC) 
                    // To show "CHECKED", we must have selected everything AND nothing can be missing/used.
                    // If Selected count equals TOTAL count, it is fully checked.
                    _SelectedCount = _TotalCount, 
                    "CHECKED",

                    // CASE D: Default to Partial
                    // This covers: 
                    // 1. User selected some but not all available.
                    // 2. User selected ALL available, but Total > Available (some are Used).
                    "PARTIAL"
                )
            },

            // 3. SVG RENDERING (No changes needed here, just re-pasting for context)
            "data:image/svg+xml;utf8," & EncodeUrl(
                "<svg width='24' height='24' viewBox='0 0 24 24' xmlns='http://www.w3.org/2000/svg'>" & Switch(
                    _State,
                    "LOCKED",
                    "<rect x='1' y='1' width='22' height='22' rx='2' ry='2' fill='#C8C6C4'/>" & 
                    "<path d='M6 12 L10 16 L18 8' stroke='#FFFFFF' stroke-width='2' fill='none' stroke-linecap='round' stroke-linejoin='round'/>",

                    "UNCHECKED",
                    "<rect x='1' y='1' width='22' height='22' rx='2' ry='2' fill='none' stroke='#605E5C' stroke-width='1.5'/>",

                    "CHECKED",
                    "<rect x='1' y='1' width='22' height='22' rx='2' ry='2' fill='#0078D4'/>" & 
                    "<path d='M6 12 L10 16 L18 8' stroke='#FFFFFF' stroke-width='2' fill='none' stroke-linecap='round' stroke-linejoin='round'/>",

                    "PARTIAL",
                    "<rect x='1' y='1' width='22' height='22' rx='2' ry='2' fill='#0078D4'/>" & 
                    "<line x1='7' y1='12' x2='17' y2='12' stroke='#FFFFFF' stroke-width='2' stroke-linecap='round'/>"
                ) & "</svg>"
            )
        )
    )
)

// Calculate how many children are AVAILABLE (Not Used)
With(
    {
        _AvailableCount: CountRows(
            Filter(col_Edit_DevCoCosts, ParentId = ThisItem.Id && Level = 3 && !Used)
        )
    },
    // If nothing is available, Disable the control. Otherwise, allow Edit.
    If(
        _AvailableCount = 0, 
        DisplayMode.Disabled, 
        DisplayMode.Edit
    )
)

// 1. SAFETY CHECK: Do not run if disabled (Double check, though DisplayMode usually handles this)
If(Self.DisplayMode <> DisplayMode.Disabled,
    With(
        {
            // Count selected items within the AVAILABLE pool
            _SelectedAvailableCount: CountRows(
                Filter(col_Edit_DevCoCosts, ParentId = ThisItem.Id && Level = 3 && Selected && !Used)
            )
        },
        
        // 2. DETERMINE ACTION
        // New Logic: If ANY available item is selected (>0) -> Turn OFF. Only if 0 are selected -> Turn ON.
        With(
            {
                _TurnOn: If(_SelectedAvailableCount = 0, true, false)
            },

            // 3. UPDATE PARENT
            UpdateIf(col_Edit_DevCoCosts, Id = ThisItem.Id, {Selected: _TurnOn});

            // 4. UPDATE CHILDREN (Only the available ones!)
            UpdateIf(
                col_Edit_DevCoCosts,
                ParentId = ThisItem.Id && Level = 3 && !Used, 
                {Selected: _TurnOn}
            );

            // 5. REFRESH
            UpdateContext({locContractDevCoCostsCahnged: true}); 
            
        )
    )
)

