Reset(rad_AddEdit_AdminContracts_RightPanel_MarginType);
Reset(txt_Add_Edit_AdminContracts_MarginPercentage);
Reset(txt_Add_Edit_AdminContracts_MarginFixedValue);
Reset(txt_Add_Edit_AdminContracts_Comments)
//Add Reset Controls for respect to the Resetting the DevCo Cost Form

// 1. UI FEEDBACK: Immediate Blocking Spinner
UpdateContext(
    {
        locIsVisibleBoPStandardAssumptionContract: false,
        varCurrentContractId: locSelectedBoPStandardContract.'BoP Contracts Standard Assumptions',
        locContractSpinnerInformationText: "Please wait, saving...",
        locIsContractVisiblePopUpSpinner: true
    }
);
// 2. MAIN LOGIC BLOCK (Wrapped in IfError)
IfError(
    With(
        {
            // PRE-CALCULATION: Resolve Technology once, instead of inside loops
            varCurrentTech: Switch(
                cmp_AdminContraacts_NestedCountryPickerColumn.SelectedNestedValue,
                "PV",
                Technology.PV,
                "Wind",
                Technology.Wind,
                "BESS",
                Technology.BESS,
                "Hydro",
                Technology.Hydro
            )
        },
        // A. PARENT RECORD: Create or Update
        With(
            {
                varUpdatedContract: Patch(
                    'BoP Contracts Standard Assumptions',
                    If(
                        IsBlank(locSelectedBoPStandardContract),
                        Defaults('BoP Contracts Standard Assumptions'),
                        locSelectedBoPStandardContract
                    ),
                    {
                        Name: Text(locContractTypeBoPAssumption) & " - " & txt_Add_Edit_AdminContracts_Description.Value,
                        Description: txt_Add_Edit_AdminContracts_Description.Value,
                        Country: cmp_AdminContraacts_NestedCountryPickerColumn.SelectedCountry,
                        Technology: varCurrentTech,
                        'Closing Date Reference': rad_Contracts_RightPanel_NewEdit_CostsUntilClosingDate.Selected.Value,
                        'Month Difference': If(
                            drp_Add_Edit_AdminContracts_MonthDifference_AddSub.Selected.Value = "+",
                            Value(txt_Add_Edit_AdminContracts_MonthDifference_Month.Value),
                            Value(txt_Add_Edit_AdminContracts_MonthDifference_Month.Value) * -1
                        ),
                        Margin: rad_Add_Edit_AdminContracts_RightPanel_NewEdit_Margin.Selected.Value,
                        'Margin Type': If(
                            rad_Add_Edit_AdminContracts_RightPanel_NewEdit_Margin.Selected.Value = 'Margin (BoP Contracts Standard Assumptions)'.Yes,
                            rad_AddEdit_AdminContracts_RightPanel_MarginType.Selected.Value,
                            Blank()
                        ),
                        'Margin Percentage': If(
                            rad_Add_Edit_AdminContracts_RightPanel_NewEdit_Margin.Selected.Value = 'Margin (BoP Contracts Standard Assumptions)'.Yes && rad_AddEdit_AdminContracts_RightPanel_MarginType.Selected.Value = 'Contract Margin Type'.Percentage,
                            Value(txt_Add_Edit_AdminContracts_MarginPercentage.Value),
                            Blank()
                        ),
                        'Margin Fixed Value': If(
                            rad_Add_Edit_AdminContracts_RightPanel_NewEdit_Margin.Selected.Value = 'Margin (BoP Contracts Standard Assumptions)'.Yes && rad_AddEdit_AdminContracts_RightPanel_MarginType.Selected.Value = 'Contract Margin Type'.'Fixed Value',
                            Value(txt_Add_Edit_AdminContracts_MarginFixedValue.Value),
                            Blank()
                        ),
                        Comment: txt_Add_Edit_AdminContracts_Comments.Value,
                        'Contract Types': locContractTypeBoPAssumption
                    }
                )
            },
            // B. CHILD RECORDS: Delete Removed Items
            RemoveIf(
                'BoP Contracts Standard Assumption DevCo Costs',
                'BoP Contract Standard Assumption'.'BoP Contracts Standard Assumptions' = varCurrentContractId && 'BoP Contracts Standard Assumption DevCo Costs' in Filter(
                    col_Edit_DevCoCosts,
                    Selected = false && !IsBlank(ContractDevCo)
                ).ContractDevCo
            );
            // C. CHILD RECORDS: Bulk Create New Items
            // OPTIMIZATION: Instead of Looping Collect, we use ForAll inside Patch to shape the table in memory
            With(
                {
                    varNewItemsToCreate: Filter(
                        col_Edit_DevCoCosts,
                        Selected = true && ContractDevCo = EmptyGUID && Level = 3
                    )
                },
                If(
                    !IsEmpty(varNewItemsToCreate),
                    Patch(
                        'BoP Contracts Standard Assumption DevCo Costs',
                        ForAll(
                            varNewItemsToCreate,
                            {
                                Name: $"{Nummer}-{Name}",
                                'BoP Contract Standard Assumption': varUpdatedContract,
                                'CAPEX Account': LookUp(
                                    'CAPEX Account Lists',
                                    'CAPEX Account List' = Id
                                ),
                                Country: cmp_AdminContraacts_NestedCountryPickerColumn.SelectedCountry,
                                Technology: varCurrentTech
                            }
                        )
                    )
                )
            );
            // D. LOCAL COLLECTION UPDATE (Update UI instantly without waiting for Refresh)
            If(
                IsBlank(locSelectedBoPStandardContract),
                // Case: Add New to List
                Collect(
                    colAdminContracts,
                    AddColumns(
                        varUpdatedContract,
                        IsFolded,
                        false
                    )
                ),
                // Case: Update Existing in List
                UpdateIf(
                    colAdminContracts,
                    'BoP Contracts Standard Assumptions' = varUpdatedContract.'BoP Contracts Standard Assumptions',
                    AddColumns(
                        varUpdatedContract,
                        IsFolded,
                        false
                    )
                )
            );
            // E. STATE MANAGEMENT
            UpdateContext({locKeepExpandedID: varUpdatedContract.'BoP Contracts Standard Assumptions'})
        )
    ),
    // F. ERROR HANDLING
    Notify(
        "Error saving Contract: " & FirstError.Message,
        NotificationType.Error
    )
);
// 3. FINAL CLEANUP & REFRESH
Concurrent(
    Refresh('BoP Contracts Standard Assumption DevCo Costs'),
    Refresh('BoP Contracts Standard Assumptions')
);
