Rules.InvariantScript:
And(
    IsNumeric(candidate),
    Not(
        IsMatch(
            candidate,
            "[.,]",
            MatchOptions.Contains
        )
    )
)

With(
    {
        varLang: Lower(
            First(
                Split(
                    Language(),
                    "-"
                )
            ).Value
        )
    },
    Switch(
        varLang,
        "en",
        IsMatch(
            candidate,
            "^[+-]?\d+(?:\.\d{0,1})?$"
        ),
        IsMatch(
            candidate,
            "^[+-]?\d+(?:\,\d{0,1})?$"
        )
    )
)

With(
    {
        varLang: Lower(
            First(
                Split(
                    Language(),
                    "-"
                )
            ).Value
        )
    },
    Switch(
        varLang,
        "en",
        IsMatch(
            candidate,
            "^[+-]?\d+(?:\.\d{0,3})?$"
        ),
        IsMatch(
            candidate,
            "^[+-]?\d+(?:\,\d{0,3})?$"
        )
    )
)

With(
    {
        varLang: Lower(
            First(
                Split(
                    Language(),
                    "-"
                )
            ).Value
        )
    },
    Switch(
        varLang,
        "en",
        IsMatch(
            candidate,
            "^[+-]?\d+(?:\.\d{0,2})?$"
        ),
        IsMatch(
            candidate,
            "^[+-]?\d+(?:\,\d{0,2})?$"
        )
    )
)

IfError(
    And(
        Value(
            candidate,
            culture
        ) >= min,
        Value(
            candidate,
            culture
        ) <= max
    ),
    false
)

With(
    {
        varLang: Lower(
            First(
                Split(
                    Language(),
                    "-"
                )
            ).Value
        )
    },
    Switch(
        varLang,
        "en",
        IsMatch(
            candidate,
            "^[+-]?\d+(?:\.\d{0,6})?$"
        ),
        IsMatch(
            candidate,
            "^[+-]?\d+(?:\,\d{0,6})?$"
        )
    )
)

IfError(
    With({ v: Value(candidate) },
        And(
            v >= min,
            v <= max
        )
    ),
    false
)

