            "^[+-]?\d+(?:\,\d{0,2})?$"
        )
    )
)

IfError(
    And(
        Value(
            candidate,
            culture
        ) >= min,
        Value(
            candidate,
            culture
        ) <= max
    ),
    false
)

With(
    {
        varLang: Lower(
            First(
                Split(
                    Language(),
                    "-"
                )
            ).Value
        )
    },
    Switch(
        varLang,
        "en",
        IsMatch(
            candidate,
            "^[+-]?\d+(?:\.\d{0,6})?$"
        ),
        IsMatch(
            candidate,
            "^[+-]?\d+(?:\,\d{0,6})?$"
        )
    )
)

IfError(
    With({ v: Value(candidate) },
        And(
            v >= min,
            v <= max
        )
    ),
    false
)

// 1. REFRESH DATA SOURCES
Refresh('BoP Contracts Standard Assumptions');
Refresh('BoP Contracts Standard Assumption DevCo Costs');
// 2. CREATE FLAT CACHE (Crucial for performance & alignment)
// We resolve lookup names here so the HTML Concat doesn't have to do it 100 times per second
ClearCollect(
    col_Costs_Flat_Cache,
    AddColumns(
        'BoP Contracts Standard Assumption DevCo Costs',
        ParentID,
        'BoP Contract Standard Assumption'.'BoP Contracts Standard Assumptions',
        CategoryName,
        'CAPEX Account'.Name,
        ParentOrder,
        RootCapexAccount.Order,
        AccountName,
        RootCapexAccount.Name
    )
);
// 3. REGENERATE MAIN COLLECTION PRESERVING EXPANSION STATES
With(
    {
        colCurrentStates: ShowColumns(
            colAdminContracts,
            vsb_bopcontractsstandardassumptionsid,
            IsFolded
        )
    },
    ClearCollect(
        colAdminContracts,
        AddColumns(
            'BoP Contracts Standard Assumptions',
            IsFolded,
            Coalesce(
                LookUp(
                    colCurrentStates,
                    vsb_bopcontractsstandardassumptionsid = 'BoP Contracts Standard Assumptions'
                ).IsFolded,
                true// Default new items to collapsed
            )
        )
    )
);
// 4. RE-CALCULATE LIMIT CHECKS
UpdateContext(
    {
        locDevContractLimitExceeded: CountIf(
            colAdminContracts,
            Country.Name = cmp_AdminContraacts_NestedCountryPickerColumn.SelectedCountry.Name && Text(Technology) = cmp_AdminContraacts_NestedCountryPickerColumn.SelectedNestedValue && 'Contract Types' = 'BoP Contract Types'.'Development Contract'
        ) >= 10,
        locConstructionContractLimitExceeded: CountIf(
            colAdminContracts,
            Country.Name = cmp_AdminContraacts_NestedCountryPickerColumn.SelectedCountry.Name && Text(Technology) = cmp_AdminContraacts_NestedCountryPickerColumn.SelectedNestedValue && 'Contract Types' = 'BoP Contract Types'.'Construction Contract'
        ) >= 10
    }
);

ControlPropertyState.AutoRuleBindingString:
Refresh('BoP Contracts Standard Assumptions');
Refresh('BoP Contracts Standard Assumption DevCo Costs');
ClearCollect(
    colAdminContracts,
    AddColumns(
        'BoP Contracts Standard Assumptions',
        IsFolded,
        If(
            'BoP Contracts Standard Assumptions' = locKeepExpandedID,
            false,
            true
        )
    )
);
UpdateContext(
    {
        locDevContractLimitExceeded: CountIf(
            colAdminContracts,
            And(
                Country.Name = cmp_AdminContraacts_NestedCountryPickerColumn.SelectedCountry.Name,
                Text(Technology) = cmp_AdminContraacts_NestedCountryPickerColumn.SelectedNestedValue,
                'Contract Types' = 'BoP Contract Types'.'Development Contract'
            )
        ) >= 10,
        locConstructionContractLimitExceeded: CountIf(
            colAdminContracts,
            And(
                Country.Name = cmp_AdminContraacts_NestedCountryPickerColumn.SelectedCountry.Name,
                Text(Technology) = cmp_AdminContraacts_NestedCountryPickerColumn.SelectedNestedValue,
                'Contract Types' = 'BoP Contract Types'.'Construction Contract'
            )
        ) >= 10
    }
);
If(
    !IsBlank(locKeepExpandedID),
    ClearCollect(
        col_View_DevCoCosts,
        GroupBy(
            AddColumns(
                Filter(
                    'BoP Contracts Standard Assumption DevCo Costs',
                    'BoP Contract Standard Assumption'.'BoP Contracts Standard Assumptions' = locKeepExpandedID
                ),
                RootCapexAccountName,
                RootCapexAccount.Name
            ),
            RootCapexAccountName,
            AggregatedCapexAccount
        )
    )
);
